struct webm_vpx_t
{
    uint8_t profile;
    uint8_t level;
    uint8_t bit_depth;
    uint8_t chroma_subsampling; // 0-4:2:0 vertical, 1-4:2:0 colocated with luma (0,0), 2-4:2:2, 3-4:4:4
    uint8_t video_full_range_flag; // 0 = legal range (e.g. 16-235 for 8 bit sample depth); 1 = full range (e.g. 0-255 for 8-bit sample depth)
    uint8_t colour_primaries; // ISO/IEC 23001-8:2016
    uint8_t transfer_characteristics;
    uint8_t matrix_coefficients;
    uint16_t codec_intialization_data_size; // must be 0
    uint8_t codec_intialization_data[1]; // not used for VP8 and VP9
};

struct flac_streaminfo_t
{
    uint16_t min_block_size; // in samples
    uint16_t max_block_size;
    uint32_t min_frame_size; // 24-bits, in bytes
    uint32_t max_frame_size;
    uint64_t sample_rate : 20; // 20-bits, [0, 655350Hz]
    uint64_t channels : 3; // (number of channels)-1, 3-bits, [1, 8]
    uint64_t bits_per_sample : 5; // (bits per sample)-1, 5-bits, [4, 32]
    uint64_t samples : 36; // total samples in stream
    uint8_t signature[16]; // MD5 signature of the unencoded audio data
};

