// Prepare a writable buffer and ensure ptr/end invariants
size_t cap = (size_t)(*FUZZ_PARAM(unsigned int) % 1024) + 1; // [1,1024]
std::vector<uint8_t> buf(cap);
uint8_t* begin = buf.data();
uint8_t* end = begin + buf.size();
// AMF0 Null marker assumed 1 byte; ensure we select a start with >=1 byte available
size_t start_max = buf.size() - 1; // ensure space for 1 byte
uint8_t* ptr = begin + (start_max ? (*FUZZ_PARAM(unsigned int) % (start_max + 1)) : 0);
// Invoke target
uint8_t* next = AMFWriteNull(ptr, end);
// Validate returned cursor is sane
FUZZ_ASSERT(next >= ptr && next <= end, "AMFWriteNull: returned cursor out of range");
// Validation: ptr/end relation enforced; ensured at least 1 byte space; asserted returned cursor bounds.

// Writable buffer for AMF0 Undefined (assume 1-byte marker)
size_t cap = (size_t)(*FUZZ_PARAM(unsigned int) % 1024) + 1;
std::vector<uint8_t> buf(cap);
uint8_t* begin = buf.data();
uint8_t* end = begin + buf.size();
size_t start_max = buf.size() - 1; // need >=1 byte
uint8_t* ptr = begin + (start_max ? (*FUZZ_PARAM(unsigned int) % (start_max + 1)) : 0);
uint8_t* next = AMFWriteUndefined(ptr, end);
FUZZ_ASSERT(next >= ptr && next <= end, "AMFWriteUndefined: returned cursor out of range");
// Validation: guaranteed >=1 byte available and checked cursor bounds.

// Writable buffer for AMF0 Object start (assume 1-byte marker)
size_t cap = (size_t)(*FUZZ_PARAM(unsigned int) % 1024) + 1;
std::vector<uint8_t> buf(cap);
uint8_t* begin = buf.data();
uint8_t* end = begin + buf.size();
size_t start_max = buf.size() - 1; // need >=1 byte
uint8_t* ptr = begin + (start_max ? (*FUZZ_PARAM(unsigned int) % (start_max + 1)) : 0);
uint8_t* next = AMFWriteObject(ptr, end);
FUZZ_ASSERT(next >= ptr && next <= end, "AMFWriteObject: returned cursor out of range");
// Validation: ensured capacity for marker and returned pointer range.

// Writable buffer for AMF0 Object end (assume 3-byte 00 00 09)
size_t need = 3;
size_t cap = (size_t)(*FUZZ_PARAM(unsigned int) % 1024) + need;
std::vector<uint8_t> buf(cap);
uint8_t* begin = buf.data();
uint8_t* end = begin + buf.size();
// choose start so remaining >= need
size_t start_max = buf.size() - need;
uint8_t* ptr = begin + (start_max ? (*FUZZ_PARAM(unsigned int) % (start_max + 1)) : 0);
uint8_t* next = AMFWriteObjectEnd(ptr, end);
FUZZ_ASSERT(next >= ptr && next <= end, "AMFWriteObjectEnd: returned cursor out of range");
// Validation: enforced >=3 bytes remaining; sanity-check next within [ptr,end].

// Writable buffer for AMF0 Typed Object marker (assume 1 byte marker written here)
size_t cap = (size_t)(*FUZZ_PARAM(unsigned int) % 1024) + 1;
std::vector<uint8_t> buf(cap);
uint8_t* begin = buf.data();
const uint8_t* end = begin + buf.size();
size_t start_max = buf.size() - 1;
uint8_t* ptr = begin + (start_max ? (*FUZZ_PARAM(unsigned int) % (start_max + 1)) : 0);
uint8_t* next = AMFWriteTypedObject(ptr, end);
FUZZ_ASSERT(next >= ptr && next <= end, "AMFWriteTypedObject: returned cursor out of range");
// Validation: buffer space >=1 ensured; returned cursor validated.

// Writable buffer for AMF0 ECMA Array marker (assume 1 byte marker here)
size_t cap = (size_t)(*FUZZ_PARAM(unsigned int) % 1024) + 1;
std::vector<uint8_t> buf(cap);
uint8_t* begin = buf.data();
const uint8_t* end = begin + buf.size();
size_t start_max = buf.size() - 1;
uint8_t* ptr = begin + (start_max ? (*FUZZ_PARAM(unsigned int) % (start_max + 1)) : 0);
uint8_t* next = AMFWriteECMAArarry(ptr, end);
FUZZ_ASSERT(next >= ptr && next <= end, "AMFWriteECMAArarry: returned cursor out of range");
// Validation: ensured >=1 byte free and checked cursor bounds.

// Writable buffer for AMF0 Boolean (assume 1-byte marker + 1 value)
size_t need = 2;
size_t cap = (size_t)(*FUZZ_PARAM(unsigned int) % 1024) + need;
std::vector<uint8_t> buf(cap);
uint8_t* begin = buf.data();
const uint8_t* end = begin + buf.size();
size_t start_max = buf.size() - need;
uint8_t* ptr = begin + (start_max ? (*FUZZ_PARAM(unsigned int) % (start_max + 1)) : 0);
uint8_t value = (uint8_t)(*FUZZ_PARAM(unsigned int) & 0xFF);
uint8_t* next = AMFWriteBoolean(ptr, end, value);
FUZZ_ASSERT(next >= ptr && next <= end, "AMFWriteBoolean: returned cursor out of range");
// Validation: enforced >=2 bytes remaining; cursor bounds asserted.

// Writable buffer for AMF0 Number (assume 1-byte marker + 8 bytes payload)
size_t need = 9;
size_t cap = (size_t)(*FUZZ_PARAM(unsigned int) % 1024) + need;
std::vector<uint8_t> buf(cap);
uint8_t* begin = buf.data();
const uint8_t* end = begin + buf.size();
size_t start_max = buf.size() - need;
uint8_t* ptr = begin + (start_max ? (*FUZZ_PARAM(unsigned int) % (start_max + 1)) : 0);
double value = *(FUZZ_PARAM(double));
uint8_t* next = AMFWriteDouble(ptr, end, value);
FUZZ_ASSERT(next >= ptr && next <= end, "AMFWriteDouble: returned cursor out of range");
// Validation: ensured >=9 bytes space; verified next within [ptr,end].

// Writable buffer for AMF0 String. For safety, use short-string path: 1 marker + 2 length + len bytes
std::string sval = FUZZ_PARAM_STR();
size_t len = sval.size();
if (len > 256) len = 256; // constrain for short string encoding
size_t need = 1 + 2 + len;
size_t cap = (size_t)(*FUZZ_PARAM(unsigned int) % 1024) + need;
std::vector<uint8_t> buf(cap);
uint8_t* begin = buf.data();
const uint8_t* end = begin + buf.size();
size_t start_max = buf.size() - need;
uint8_t* ptr = begin + (start_max ? (*FUZZ_PARAM(unsigned int) % (start_max + 1)) : 0);
// Invoke target
uint8_t* next = AMFWriteString(ptr, end, sval.data(), len);
FUZZ_ASSERT(next >= ptr && next <= end, "AMFWriteString: returned cursor out of range");
// Validation: enforced remaining capacity for marker+len+payload; checked cursor range.

// Writable buffer for AMF0 Date (assume 1 marker + 8-byte millis + 2-byte tz)
size_t need = 11;
size_t cap = (size_t)(*FUZZ_PARAM(unsigned int) % 1024) + need;
std::vector<uint8_t> buf(cap);
uint8_t* begin = buf.data();
const uint8_t* end = begin + buf.size();
size_t start_max = buf.size() - need;
uint8_t* ptr = begin + (start_max ? (*FUZZ_PARAM(unsigned int) % (start_max + 1)) : 0);
double ms = *(FUZZ_PARAM(double));
int16_t tz = *(FUZZ_PARAM(int16_t));
uint8_t* next = AMFWriteDate(ptr, end, ms, tz);
FUZZ_ASSERT(next >= ptr && next <= end, "AMFWriteDate: returned cursor out of range");
// Validation: ensured >=11 bytes; validated returned pointer bounds.

// Writable buffer for AMF0 property name (assume 2-byte length + name bytes)
std::string name = FUZZ_PARAM_STR();
size_t nlen = name.size();
if (nlen > 256) nlen = 256; // keep small and within typical 16-bit length
size_t need = 2 + nlen;
size_t cap = (size_t)(*FUZZ_PARAM(unsigned int) % 1024) + need;
std::vector<uint8_t> buf(cap);
uint8_t* begin = buf.data();
const uint8_t* end = begin + buf.size();
size_t start_max = buf.size() - need;
uint8_t* ptr = begin + (start_max ? (*FUZZ_PARAM(unsigned int) % (start_max + 1)) : 0);
uint8_t* next = AMFWriteNamed(ptr, end, name.data(), nlen);
FUZZ_ASSERT(next >= ptr && next <= end, "AMFWriteNamed: returned cursor out of range");
// Validation: ensured enough bytes for name field; checked cursor range.

// Writable buffer for AMF0 named string: name(2+nlen) + value(1 marker + 2 + vlen)
std::string name = FUZZ_PARAM_STR();
std::string value = FUZZ_PARAM_STR();
size_t nlen = name.size();
size_t vlen = value.size();
if (nlen > 128) nlen = 128;
if (vlen > 256) vlen = 256; // short string encoding path
size_t need = (2 + nlen) + (1 + 2 + vlen);
size_t cap = (size_t)(*FUZZ_PARAM(unsigned int) % 1024) + need;
std::vector<uint8_t> buf(cap);
uint8_t* begin = buf.data();
const uint8_t* end = begin + buf.size();
size_t start_max = buf.size() - need;
uint8_t* ptr = begin + (start_max ? (*FUZZ_PARAM(unsigned int) % (start_max + 1)) : 0);
uint8_t* next = AMFWriteNamedString(ptr, end, name.data(), nlen, value.data(), vlen);
