import random
from typing import List

def _be16(n: int) -> bytes:
    return bytes([(n >> 8) & 0xFF, n & 0xFF])


def _be32(n: int) -> bytes:
    return bytes([
        (n >> 24) & 0xFF,
        (n >> 16) & 0xFF,
        (n >> 8) & 0xFF,
        n & 0xFF,
    ])


def _rand_string(rng: random.Random, min_len: int, max_len: int) -> bytes:
    # Mix ASCII, UTF-8 multibyte, and some edge bytes
    pools: List[bytes] = [
        b"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789 _-./~",
        # Some UTF-8 sequences
        "\u00A9\u00AE\u2122\u20AC\u2603\u03B1\u03B2\u03B3\u4F60\u597D".encode("utf-8"),
        bytes([0x00, 0x01, 0x02, 0x7F, 0xC2, 0xA9, 0xE2, 0x82, 0xAC]),
    ]
    length = rng.randint(min_len, max_len)
    out = bytearray()
    while len(out) < length:
        pool = pools[rng.randrange(len(pools))]
        # pick a chunk of up to 4 bytes to keep variety but control size
        take = rng.randint(1, min(4, max(1, length - len(out))))
        # choose a starting index ensuring we can take bytes
        if len(pool) == 0:
            continue
        start = rng.randrange(len(pool))
        # wrap if needed
        chunk = bytearray()
        for i in range(take):
            chunk.append(pool[(start + i) % len(pool)])
        out.extend(chunk)
    # trim to exact length
    if len(out) > length:
        del out[length:]
    return bytes(out)


def _build_amf0_short_string(payload: bytes) -> bytes:
    # AMF0 short string: 0x02, u16-be length, bytes
    if len(payload) > 0xFFFF:
        payload = payload[:0xFFFF]
    return b"\x02" + _be16(len(payload)) + payload


def _build_amf0_long_string(payload: bytes) -> bytes:
    # AMF0 long string: 0x0C, u32-be length, bytes
    return b"\x0C" + _be32(len(payload)) + payload


def generate(seed: int) -> bytes:
    """
    Generate a valid AMF0 string (short or long) frame including the marker and length.
    This targets the AMFReadString fuzzer stub which expects either:
      short: 0x02 [u16-be length] [bytes]
      long:  0x0C [u32-be length] [bytes]
    The function returns a bytes buffer to seed FUZZ_PARAM_FILENAME / FUZZ_PARAM_STR.
    """
    rng = random.Random(seed)

    # Decide between short and long string with some bias toward short (as the stub caps short to 200)
    is_long = rng.random() < 0.35

    if not is_long:
        # short string up to 200 (per stub cap), but vary sizes including 0 and boundary 200
        choices = [0, 1, 2, 3, 31, 32, 63, 64, 127, 128, 199, 200]
        if rng.random() < 0.6:
            length = rng.randint(0, 200)
        else:
            length = choices[rng.randrange(len(choices))]
        payload = _rand_string(rng, length, length)
        return _build_amf0_short_string(payload)
    else:
        # long string: include a range of interesting sizes while keeping under 4096 total
        # Header is 1 + 4 = 5 bytes, keep payload <= 4091
        boundary_sizes = [0, 1, 2, 255, 256, 511, 512, 1023, 1024, 2047, 2048, 3072, 4091]
        if rng.random() < 0.6:
            length = rng.randint(0, 4091)
        else:
            length = boundary_sizes[rng.randrange(len(boundary_sizes))]
        payload = _rand_string(rng, length, length)
        return _build_amf0_long_string(payload)

