# Generator for AMF3 inline string frame
# Format: 0x06 | U29((len<<1)|1) | len bytes payload (UTF-8)
# U29 variable-length, 1-4 bytes as per AMF3: high bit continuation for first 3 bytes, last byte full 8 bits.

def _encode_u29(value: int) -> bytes:
    # value is 29-bit unsigned int
    if value < 0x80:
        return bytes([value])
    elif value < 0x4000:
        return bytes([(value >> 7) | 0x80, value & 0x7F])
    elif value < 0x200000:
        return bytes([(value >> 14) | 0x80, ((value >> 7) & 0x7F) | 0x80, value & 0x7F])
    else:
        return bytes([(value >> 22) | 0x80, ((value >> 15) & 0x7F) | 0x80, ((value >> 8) & 0x7F) | 0x80, value & 0xFF])

def _rand_utf8_string(rng: random.Random, length: int) -> bytes:
    # Build a UTF-8 string with a mix of ASCII and multibyte sequences, exactly length bytes
    # Strategy: generate code points, encode, trim/pad to exact length
    pieces = []
    while len(b"".join(pieces)) < length:
        t = rng.random()
        if t < 0.6:
            # ASCII printable + some control edge cases (including NUL)
            ch = rng.choice([0x00, 0x09, 0x0A, 0x0D] + list(range(0x20, 0x7F)))
        elif t < 0.85:
            # 2-byte UTF-8
            ch = rng.randint(0x80, 0x7FF)
        elif t < 0.97:
            # 3-byte UTF-8
            ch = rng.randint(0x800, 0xFFFF)
            # avoid surrogates (D800-DFFF)
            if 0xD800 <= ch <= 0xDFFF:
                ch = 0xE000 + (ch - 0xD800)
        else:
            # 4-byte UTF-8 (up to U+10FFFF)
            ch = rng.randint(0x10000, 0x10FFFF)
        try:
            enc = chr(ch).encode('utf-8')
        except Exception:
            continue
        pieces.append(enc)
        if len(b"".join(pieces)) > length:
            break
    data = b"".join(pieces)
    if len(data) > length:
        # Trim without cutting a UTF-8 sequence: backtrack to a valid prefix of desired length
        data = data[:length]
        # Ensure we don't end in the middle of a multibyte sequence
        # Find the start of the last character
        cut = length
        # Move back while byte is a continuation byte (10xxxxxx)
        while cut > 0 and (data[cut-1] & 0xC0) == 0x80:
            cut -= 1
        # Determine expected length of lead byte sequence
        if cut < length:
            lead = data[cut]
            if (lead & 0xE0) == 0xC0:
                need = 2
            elif (lead & 0xF0) == 0xE0:
                need = 3
            elif (lead & 0xF8) == 0xF0:
                need = 4
            else:
                need = 1
            if cut + need > length:
                data = data[:cut]
        # pad with NULs if we trimmed more than needed
        if len(data) < length:
            data += b"\x00" * (length - len(data))
    elif len(data) < length:
        data += b"\x00" * (length - len(data))
    return data

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose interesting lengths prioritizing small but include boundaries
    interesting = [0, 1, 2, 3, 4, 5, 6, 7, 14, 15, 16, 17, 63, 64, 65, 126, 127, 128, 199, 200]
    if rng.random() < 0.7:
        length = rng.choice(interesting)
    else:
        length = rng.randint(0, 200)
    # Cap to 256 buffer capacity of stub, but stub uses outbuf 256 and len<=200; we keep <=200
    header_val = (length << 1) | 1  # inline flag
    hdr = _encode_u29(header_val)
    payload = _rand_utf8_string(rng, length)
    return bytes([0x06]) + hdr + payload

