# This generator creates a small AV1 Annex B style bytestream consisting of a
# sequence of length-prefixed OBUs, suitable for feeding aom_av1_annexb_split.
# It aims to be valid enough to parse and exercise multiple handler paths:
# - It will include a Sequence Header OBU (type=1) first to help parsers.
# - It may include additional OBUs: Temporal Delimiter (type=2), Frame Header (type=6),
#   and Padding (type=15), among others.
# - It uses the Annex B length-delimited format: [leb128 obu_size][obu_header+payload].
# - OBU headers are formed per spec basics: forbidden=0, obu_type, extension/size fields.
# - leb128 encodes obu_size (header+payload) as required by Annex B.
# The payloads are minimal/dummy but structurally plausible so splitters can walk them.

# OBU types per spec (selected subset)
OBU_SEQUENCE_HEADER = 1
OBU_TEMPORAL_DELIMITER = 2
OBU_FRAME_HEADER = 6
OBU_TILE_GROUP = 7
OBU_METADATA = 5
OBU_PADDING = 15


def _leb128_encode(value: int) -> bytes:
    # Unsigned LEB128
    out = bytearray()
    v = value & 0xFFFFFFFFFFFFFFFF
    while True:
        byte = v & 0x7F
        v >>= 7
        if v:
            out.append(byte | 0x80)
        else:
            out.append(byte)
            break
    return bytes(out)


def _obu_header(obu_type: int, obu_extension_flag: int = 0, obu_has_size_field: int = 1, obu_reserved_1bit: int = 0) -> int:
    # Bits: forbidden(1)=0, type(4), ext(1), has_size(1), reserved(1)
    return ((0 & 1) << 7) | ((obu_type & 0x0F) << 3) | ((obu_extension_flag & 1) << 2) | ((obu_has_size_field & 1) << 1) | (obu_reserved_1bit & 1)


def _rand_bytes(rng: random.Random, n: int) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(n))


def _make_sequence_header(rng: random.Random) -> bytes:
    # Minimal plausible sequence header payload. Real bitstream syntax is complex; for splitters,
    # having a non-empty payload is often sufficient. We'll create a few bytes that look structured.
    # Use a couple of random bytes and some constrained fields.
    payload_len = rng.randint(5, 20)
    payload = bytearray(_rand_bytes(rng, payload_len))
    # Nudge some bits to sane values (profile [0..2], still_picture=0/1, reduced_still_picture_header=0/1)
    if payload_len >= 1:
        payload[0] = (payload[0] & 0xFC) | rng.randint(0, 3)  # 2 bits profile-ish
    return bytes(payload)


def _make_temporal_delimiter() -> bytes:
    # Temporal delimiter has empty payload typically
    return b""


def _make_frame_header(rng: random.Random) -> bytes:
    # Minimal dummy frame header payload
    n = rng.randint(3, 12)
    return _rand_bytes(rng, n)


def _make_tile_group(rng: random.Random) -> bytes:
    n = rng.randint(1, 16)
    return _rand_bytes(rng, n)


def _make_metadata(rng: random.Random) -> bytes:
    # First byte: metadata_type (0..7 range used here)
    meta_type = rng.randint(0, 7)
    rest = _rand_bytes(rng, rng.randint(0, 10))
    return bytes([meta_type]) + rest


def _make_padding(rng: random.Random) -> bytes:
    # Padding payload is ignore-able bytes; fill with 0x00/0xFF
    n = rng.randint(0, 16)
    if n == 0:
        return b""
    return bytes([0x00 if (i % 2 == 0) else 0xFF for i in range(n)])


def _wrap_annexb_obu(obu_type: int, payload: bytes) -> bytes:
    header_byte = _obu_header(obu_type)
    obu_content = bytes([header_byte]) + payload
    leb = _leb128_encode(len(obu_content))
    return leb + obu_content


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Build a sequence of OBUs. Ensure first is Sequence Header to increase validity.
    obus: List[bytes] = []

    # Optionally start with a Temporal Delimiter to exercise that path
    if rng.random() < 0.6:
        obus.append(_wrap_annexb_obu(OBU_TEMPORAL_DELIMITER, _make_temporal_delimiter()))

    # Mandatory sequence header
    obus.append(_wrap_annexb_obu(OBU_SEQUENCE_HEADER, _make_sequence_header(rng)))

    # Add a few additional OBUs
    count = rng.randint(1, 6)
    for _ in range(count):
        choice = rng.random()
        if choice < 0.25:
            obus.append(_wrap_annexb_obu(OBU_FRAME_HEADER, _make_frame_header(rng)))
        elif choice < 0.50:
            obus.append(_wrap_annexb_obu(OBU_TILE_GROUP, _make_tile_group(rng)))
        elif choice < 0.75:
            obus.append(_wrap_annexb_obu(OBU_METADATA, _make_metadata(rng)))
        else:
            obus.append(_wrap_annexb_obu(OBU_PADDING, _make_padding(rng)))

    # Occasionally add trailing padding
    if rng.random() < 0.3:
        obus.append(_wrap_annexb_obu(OBU_PADDING, _make_padding(rng)))

    data = b"".join(obus)

    # Ensure size cap
    if len(data) > 4096:
        data = data[:4096]

