import random
import struct
from typing import List

# Generator for valid G.711 A-law payloads
# - Each byte is an independent 8-bit A-law sample (RFC 3551/ITU-T G.711)
# - No headers; any sequence of bytes is valid audio payload
# - To exercise muxer behavior, we generate a variety of lengths and
#   patterns: silence, constant tones, alternating values, ramps, and
#   pseudo-random samples. All are valid A-law bytes.

# A-law companding helpers (linear PCM -> A-law). Not strictly needed for
# validity (any byte is valid), but useful to craft meaningful signals like
# silence and tones.
# Implementation adapted to standard G.711 A-law mapping.

def _linear_to_alaw(pcm_val: int) -> int:
    # Clamp to 16-bit signed
    if pcm_val > 32767:
        pcm_val = 32767
    elif pcm_val < -32768:
        pcm_val = -32768

    SIGN_BIT = 0x80
    QUANT_MASK = 0x0F
    SEG_SHIFT = 4
    SEG_MASK = 0x70

    pcm = pcm_val
    mask = 0xD5  # A-law complement mask

    if pcm >= 0:
        sign = 0
        pcm = pcm if pcm < 32768 else 32767
    else:
        sign = SIGN_BIT
        pcm = -pcm - 1  # A-law uses complement for negative values

    # Finding segment
    def _seg(x: int) -> int:
        if x > 0x1FFF:
            return 7
        if x > 0x0FFF:
            return 6
        if x > 0x07FF:
            return 5
        if x > 0x03FF:
            return 4
        if x > 0x01FF:
            return 3
        if x > 0x00FF:
            return 2
        if x > 0x007F:
            return 1
        return 0

    seg = _seg(pcm)

    if seg >= 1:
        aval = sign | (seg << SEG_SHIFT) | ((pcm >> (seg + 3)) & QUANT_MASK)
    else:
        aval = sign | (seg << SEG_SHIFT) | ((pcm >> 4) & QUANT_MASK)

    return aval ^ mask


def _gen_silence(length: int) -> bytes:
    # Linear PCM silence (0) mapped to A-law
    sample = _linear_to_alaw(0)
    return bytes([sample] * length)


def _gen_alt_pattern(length: int, a: int, b: int) -> bytes:
    a &= 0xFF
    b &= 0xFF
    return bytes((a if (i & 1) == 0 else b) for i in range(length))


def _gen_ramp(length: int, start: int, step: int) -> bytes:
    start &= 0xFF
    return bytes(((start + i * step) & 0xFF) for i in range(length))


def _gen_random(length: int, rng: random.Random) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(length))


def _gen_sine_alaw(length: int, freq_hz: float, sample_rate: int, amp: int, rng: random.Random) -> bytes:
    # Build a simple sine wave in 16-bit PCM then compand to A-law
    # amp in 0..32767
    import math
    out = bytearray(length)
    phase = rng.random() * 2 * math.pi
    for n in range(length):
        t = (n / sample_rate) * (2 * math.pi * freq_hz) + phase
        pcm = int(amp * math.sin(t))
        out[n] = _linear_to_alaw(pcm)
    return bytes(out)


def _choose_length(rng: random.Random) -> int:
    # Favor a range of sizes up to 2048 as per stub cap
    # Include small, medium, and near-limit sizes
    choices = [1, 2, 8, 13, 64, 128, 160, 256, 320, 480, 512, 800, 1024, 1500, 1800, 2048]
    weights = [3, 3, 4, 2, 5, 6, 6, 5, 6, 5, 5, 4, 4, 3, 3, 2]
    return rng.choices(choices, weights=weights, k=1)[0]


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    length = _choose_length(rng)

    # Choose pattern type
    patterns = [
        "silence",
        "alt_ff_00",
        "alt_55_aa",
        "ramp",
        "random",
        "sine_1k",
        "sine_low",
        "sine_high",
    ]
    # Bias toward random and common telephony-related sizes/patterns
    weights = [5, 3, 3, 4, 8, 5, 4, 4]
    kind = rng.choices(patterns, weights=weights, k=1)[0]

    if kind == "silence":
        return _gen_silence(length)
    elif kind == "alt_ff_00":
        return _gen_alt_pattern(length, 0xFF, 0x00)
    elif kind == "alt_55_aa":
        return _gen_alt_pattern(length, 0x55, 0xAA)
    elif kind == "ramp":
        start = rng.randrange(0, 256)
        step = rng.choice([1, 3, 5, 7, 9, 13, 17, 31])
        return _gen_ramp(length, start, step)
    elif kind == "random":
        return _gen_random(length, rng)
    elif kind == "sine_1k":
        # Typical telephony 8kHz sample rate with 1kHz tone
        return _gen_sine_alaw(length, freq_hz=1000.0, sample_rate=8000, amp=12000, rng=rng)
    elif kind == "sine_low":
        f = rng.choice([200.0, 300.0, 440.0])
        return _gen_sine_alaw(length, freq_hz=f, sample_rate=8000, amp=15000, rng=rng)
    elif kind == "sine_high":
        f = rng.choice([2000.0, 2600.0, 3000.0])
        return _gen_sine_alaw(length, freq_hz=f, sample_rate=8000, amp=10000, rng=rng)

    # Fallback
    return _gen_random(length, rng)
